#include <iostream> 
using namespace std;
int main() {
unsigned chara = 6;// 二进制: 0000 0110
unsigned charb = 3;// 二进制: 0000 0011
cout <<"a & b = "<< (int)(a & b) << endl;// 结果: 2
cout <<"a | b = "<< (int)(a | b) << endl;// 结果: 7
cout <<"a ^ b = "<< (int)(a ^ b) << endl;// 结果: 5
return0; 
}

